package ama.storage;
import ama.transcript.*;import ama.model.*;import ama.task.*;import java.util.*;import static org.junit.jupiter.api.Assertions.*;
class Task09MinutesPaginationIT extends Task09MinutesHttpIT {
 @Override void afterExternal(Map<String,Object> candidate,MinutesExternalPreparation preparation,ControlledMinutesClient client,JdbcExternalOperations operations)throws Exception{
  super.afterExternal(candidate,preparation,client,operations);var authority=ama.api.Task09RuntimeProbe.components(app).authority();var prep=new JdbcMinutesGenerationPreparation(authority,this::snapshot,pin,prompt,model,new TranscriptAcquisitionBudget(16777216,16777216,16777216,268435456,134217728,33554432,128,256,256));var outbox=new JdbcOutbox(source,new MinutesEventReferences(source).validators());var queue=new JdbcTaskQueue(source,new JdbcSubjectFences(source,Set.of("MEETING")),outbox,Map.of("MINUTES_GENERATE_V1",authority.minutesTaskPolicy()));var commands=new JdbcMinutesGenerationCommands(authority,prep,queue,outbox,new ama.audit.JdbcAuditAdapter(source));var accepted=new HashSet<String>();accepted.add((String)candidate.get("task_id"));for(int n=0;n<3;n++){var result=(Map<?,?>)commands.enqueue(actor(),meeting,"page-"+n,4,UUID.randomUUID().toString()).get("result");accepted.add((String)result.get("taskId"));}
  String base="/meetings/"+meeting+"/minutes";var first=call("GET",base+"/generation-tasks?limit=2","",null);assertEquals(200,first.statusCode(),first.body());String cursor=body(first).get("nextCursor").asText();assertFalse(cursor.matches("[0-9a-f-]{36}"),"Cursor must bind meeting/filter/order/highwater, not a bare row UUID");assertEquals(candidate.get("id"),body(first).get("items").get(0).get("candidateId").asText());
  var later=(Map<?,?>)commands.enqueue(actor(),meeting,"after-highwater",4,UUID.randomUUID().toString()).get("result");var second=call("GET",base+"/generation-tasks?limit=2&cursor="+cursor,"",null);assertEquals(200,second.statusCode(),second.body());assertEquals(2,body(second).get("items").size());assertTrue(body(second).get("nextCursor").isNull());var actual=new HashSet<String>();for(var page:List.of(body(first),body(second)))for(var item:page.get("items"))actual.add(item.get("taskId").asText());assertEquals(accepted,actual);assertFalse(actual.contains(later.get("taskId")));assertEquals(400,call("GET",base+"/candidates?state=ALL&cursor="+cursor,"",null).statusCode());assertEquals(400,call("GET",base+"/generation-tasks?cursor="+cursor+"x","",null).statusCode());
  java.nio.file.Files.writeString(receipt.resolve("actual-keyset-pagination.json"),json.writeValueAsString(Map.of("firstCount",2,"secondCount",2,"highwaterExcludedLaterTask",later.get("taskId"),"actualTasks",actual,"crossFilterDenied",true,"candidateRelationVerified",candidate.get("id"))));
 }
}
